// Build deterministic notification task and event key with deduplication
const items = $input.all();
const tasks = [];
const seenKeys = new Set();

for (const item of items) {
  const data = item.json;
  const apptId = data.id || data.appointmentId;
  if (!apptId) continue;

  const status = (data.status || 'pending').toLowerCase();
  const patientId = data.patientId || '';
  const doctorId = data.doctorId || '';
  const doctorName = data.doctorName || 'Doctor';
  const patientName = data.patientName || 'Patient';

  const updatedSeconds = (data.updatedAt && data.updatedAt._seconds) 
    ? data.updatedAt._seconds 
    : ((data.requestedAt && data.requestedAt._seconds) ? data.requestedAt._seconds : '0');

  const eventKey = `${apptId}_${status}_${updatedSeconds}`;
  if (seenKeys.has(eventKey)) continue;
  seenKeys.add(eventKey);

  let recipientUid = '';
  let recipientRole = '';
  let senderUid = '';
  let title = '';
  let message = '';
  let telegramText = '';
  let notifType = 'appointment';

  let dateTimeStr = 'Scheduled Time';
  if (data.dateTime && data.dateTime._seconds) {
    dateTimeStr = new Date(data.dateTime._seconds * 1000).toLocaleString();
  } else if (data.dateTime) {
    dateTimeStr = new Date(data.dateTime).toLocaleString();
  }

  if (status === 'pending') {
    recipientUid = doctorId;
    recipientRole = 'doctor';
    senderUid = patientId;
    title = 'New Appointment Request';
    message = `New appointment request from ${patientName} for ${dateTimeStr}.`;
    telegramText = `🏥 *Continuum Health*

*New Appointment Request*
Patient ${patientName} requested an appointment for ${dateTimeStr}.`;
    notifType = 'appointment_request';
  } else if (status === 'approved') {
    recipientUid = patientId;
    recipientRole = 'patient';
    senderUid = doctorId;
    title = 'Appointment Approved';
    message = `Your appointment with Dr. ${doctorName} scheduled for ${dateTimeStr} has been approved.`;
    telegramText = `🏥 *Continuum Health*

*Appointment Approved*
Your appointment with Dr. ${doctorName} scheduled for ${dateTimeStr} has been approved.`;
    notifType = 'appointment_approved';
  } else if (status === 'rejected') {
    recipientUid = patientId;
    recipientRole = 'patient';
    senderUid = doctorId;
    title = 'Appointment Rejected';
    message = `Your appointment request with Dr. ${doctorName} was rejected.`;
    telegramText = `🏥 *Continuum Health*

*Appointment Rejected*
Your appointment request with Dr. ${doctorName} was rejected.`;
    notifType = 'appointment_rejected';
  } else if (status === 'cancelled') {
    recipientUid = doctorId;
    recipientRole = 'doctor';
    senderUid = patientId;
    title = 'Appointment Cancelled';
    message = `${patientName} cancelled their scheduled appointment.`;
    telegramText = `🏥 *Continuum Health*

*Appointment Cancelled*
${patientName} cancelled their scheduled consultation for ${dateTimeStr}.`;
    notifType = 'appointment_cancelled';
  } else if (status === 'completed') {
    recipientUid = patientId;
    recipientRole = 'patient';
    senderUid = doctorId;
    title = 'Appointment Completed';
    message = `Your consultation with Dr. ${doctorName} is completed.`;
    telegramText = `🏥 *Continuum Health*

*Consultation Completed*
Your consultation with Dr. ${doctorName} is completed. Prescriptions & reports are available in your health vault.`;
    notifType = 'appointment_completed';
  } else if (status === 'missed') {
    recipientUid = patientId;
    recipientRole = 'patient';
    senderUid = doctorId;
    title = 'Appointment Missed';
    message = `You missed your scheduled appointment with Dr. ${doctorName} at ${dateTimeStr}.`;
    telegramText = `Continuum Health Alert

Your appointment with Dr. ${doctorName}
scheduled for ${dateTimeStr} was missed.

Please reschedule your appointment if required.`;
    notifType = 'appointment_missed';
  }

  if (recipientUid) {
    tasks.push({
      json: {
        eventKey,
        appointmentId: apptId,
        status,
        recipientUid,
        recipientRole,
        senderUid,
        patientId,
        doctorId,
        title,
        message,
        telegramText,
        notifType,
        doctorName,
        patientName,
        dateTime: data.dateTime,
        dateTimeStr
      }
    });
  }
}

return tasks;

// Prepare in-app notification and audit log payload
const task = $('Build Notification Tasks').item.json;
const user = $('Get Recipient User').item.json || {};
const notifId = `notif_${task.eventKey}`;

return [{
  json: {
    notificationId: notifId,
    recipientUid: task.recipientUid,
    recipientRole: task.recipientRole,
    senderUid: task.senderUid,
    patientId: task.patientId,
    doctorId: task.doctorId,
    title: task.title,
    message: task.message,
    type: task.notifType,
    relatedId: task.appointmentId,
    appointmentId: task.appointmentId,
    status: task.status,
    read: false,
    isRead: false,
    telegramChatId: user.telegramChatId || null,
    deliveryStatus: user.telegramConnected ? 'sent' : 'in_app_only',
    createdAt: new Date().toISOString()
  }
}];
